						{ t = "accept", quest = 91862, title = "Lumina Windsinger", npc = 248755, npcName = "Lumina Windsinger", minLevel = 18, qlvl = 22, map = 1421, x = 65.51, y = 23.47, f = "e" },
						{ t = "collect", quest = 91862, title = "Lumina Windsinger", item = 267412, itemName = "Fenris Isle Key", count = 1, oi = 1, map = 1421, x = 65.57, y = 23.32, f = "e", spotsPacked = "65.7,24,,51,23", note = "{item:267412}, from the Rot Hide gnolls", fromNpcs = { { npc = 1942, npcName = "Rot Hide Savage" }, { npc = 1943, npcName = "Raging Rot Hide" }, { npc = 1944, npcName = "Rot Hide Bruiser" }, { npc = 1948, npcName = "Snarlmane" } } },
