						{ t = "collect", npc = 248840, npcName = "Trevan Rol", item = 267454, itemName = "Trevan's Weapon Notes", map = 1421, x = 43.34, y = 41.02, f = "e", note = "{item:267454}: talk to {npc:248840}" },
