					},
				},
				{
					title = "{npc:248840}",
					note = "Bring the lumber, the ingot and the gem to {npc:248840} in the {area:228}. He gives you a {item:268192} for a smith in {area:272}: keep it in your bags.",
					goals = {
						{ t = "turnin", quest = 95036, title = "A Moon-Kissed Blade", npc = 248840, npcName = "Trevan Rol", map = 1421, x = 43.34, y = 41.02, f = "e" },
						{ t = "accept", quest = 95111, title = "An Underrated Talent", npc = 248840, npcName = "Trevan Rol", minLevel = 20, qlvl = 25, map = 1421, x = 43.34, y = 41.02, f = "e" },
					},
				},
