						{ t = "turnin", quest = 95125, title = "Ott's Masterwork", npc = 3539, npcName = "Ott", map = 1424, x = 60.43, y = 26.18, z = 57, f = "e" },
						{ t = "accept", quest = 95126, title = "The Moonsilver Blade", npc = 3539, npcName = "Ott", minLevel = 20, qlvl = 25, map = 1424, x = 60.43, y = 26.18, z = 57, f = "e", note = "{npc:3539} gives you {quest:95125}" },
					},
