			names = { ["area:263"] = "Cleft", ["area:272"] = "Tarren Mill", ["area:287"] = "Hillsbrad", ["area:380"] = "Crossroads", ["area:382"] = "Sludge Fen", ["area:392"] = "Ratchet", ["item:18160"] = "Recipe: Thistle Tea", ["item:2928"] = "Dust of Decay", ["item:3371"] = "Empty Vial", ["item:5060"] = "Thieves' Tools", ["item:6947"] = "Instant Poison", ["item:7676"] = "Thistle Tea", ["item:8051"] = "Flare Gun", ["item:8066"] = "Fizzule's Whistle", ["item:8072"] = "Silixiz's Tower Key", ["item:8073"] = "Cache of Zanzil's Altered Mixture", ["item:8074"] = "Gallywix's Head", ["item:8095"] = "Hinott's Oil", ["npc:2216"] = "Apothecary Lydon", ["npc:2391"] = "Serge Hinott", ["npc:3401"] = "Shenthul", ["npc:7233"] = "Taskmaster Fizzule", ["npc:7287"] = "Foreman Silixiz", ["npc:7288"] = "Grand Foreman Puzik Gallywix", ["npc:7310"] = "Mutated Venture Co. Drone", ["object:129127"] = "Gallywix's Lockbox", ["object:172960"] = "Cleft of Shadow", ["object:172982"] = "Valley of Strength", ["quest:2458"] = "Deep Cover", ["quest:2460"] = "The Shattered Salute", ["spell:1776"] = "Gouge", ["spell:1804"] = "Pick Lock", ["spell:1943"] = "Rupture", ["spell:2098"] = "Eviscerate", ["spell:5277"] = "Evasion", ["spell:921"] = "Pick Pocket", ["spell:9810"] = "Touch of Zanzil", ["zone:1421"] = "Silverpine Forest", ["zone:1454"] = "Orgrimmar", ["zone:1458"] = "Undercity" },
			steps = {
				{
					title = "Lockpicking practice",
					note = "{object:129127} at the end of the tower job needs Lockpicking of about 70-75. Train {spell:1804} from Gest or {npc:3401} in the {object:172960} if you lack it, carry {item:5060}, and pick the Buccaneer's Strongboxes on the middle deck of the Tide Razor, the beached pirate ship south of {area:392}: they come back fast. Your cap rises 5 per level.",
					goals = {
						{ t = "level", level = 20 },
						{ t = "goto", text = "Tide Razor", map = 1413, x = 64.4, y = 45.4, f = "e" },
						{ t = "task", text = "Lockpicking about 75: pick the Buccaneer's Strongboxes on the Tide Razor", optional = true },
					},
				},
				{
					title = "{quest:2460}",
					note = "{npc:3401} stands in the {object:172960}, the canyon under the {object:172982}. Take the quest and wait: he speaks three lines and salutes you. After his third line, target him and type /salute. If it does not count, abandon the quest and take it again. The tower job ahead is built around Ambush, which needs a dagger: if you have none, Kareth, the blade merchant in the {object:172960}, sells a Jambiya.",
					goals = {
						{ t = "accept", quest = 2460, title = "The Shattered Salute", npc = 3401, npcName = "Shenthul", minLevel = 20, qlvl = 20, map = 1454, x = 43.05, y = 53.74, z = 7.8, f = "e" },
						{ t = "complete", quest = 2460, title = "The Shattered Salute", map = 1454, x = 43.05, y = 53.74, f = "e", note = "/salute {npc:3401}" },
						{ t = "turnin", quest = 2460, title = "The Shattered Salute", npc = 3401, npcName = "Shenthul", map = 1454, x = 43.05, y = 53.74, z = 7.8, f = "e" },
						{ t = "accept", quest = 2458, title = "Deep Cover", npc = 3401, npcName = "Shenthul", minLevel = 20, qlvl = 20, pre = { 2460 }, preTitles = { [2460] = "The Shattered Salute" }, map = 1454, x = 43.05, y = 53.74, z = 7.8, f = "e", note = "{quest:2458}: keep the {item:8051}" },
					},
				},
				{
					title = "{npc:7233}",
					note = "Fly to the {area:380} and head north to the Venture Co. tower above the {area:382}. Fizzule stands under a tree east of the tower, outside it, and is hostile until signalled. Target him from about 50 yards and fire the {item:8051} twice, then walk up in front of him and /salute. In any other order he attacks. Lost the {item:8051}? Abandon and retake from {npc:3401}.",
					goals = {
						{ t = "use", item = 8051, itemName = "Flare Gun", map = 1413, x = 55.4, y = 5.6, f = "e", note = "{item:8051}, twice, at Fizzule" },
						{ t = "turnin", quest = 2458, title = "Deep Cover", npc = 7233, npcName = "Taskmaster Fizzule", map = 1413, x = 55.44, y = 5.56, z = 91.8, f = "e", note = "{npc:7233}: {item:8066}", rewards = { items = { { item = 8066, itemName = "Fizzule's Whistle" } } } },
						{ t = "accept", quest = 2478, title = "Mission: Possible But Not Probable", npc = 7233, npcName = "Taskmaster Fizzule", minLevel = 20, qlvl = 24, pre = { 2458 }, preTitles = { [2458] = "Deep Cover" }, map = 1413, x = 55.44, y = 5.56, z = 91.8, f = "e" },
					},
				},
				{
					title = "{item:8072}",
					note = "Keep {item:8066} in your bags and use it on him every time you come near, or he turns hostile. {npc:7287} (level 22) walks by the tower: hug the wall, stealth up behind him and {spell:921} the key. Killing him does not give it; if his pockets are empty, kill him and wait 4 1/2 minutes for him to come back.",
					goals = {
						{ t = "collect", quest = 2478, title = "Mission: Possible But Not Probable", item = 8072, itemName = "Silixiz's Tower Key", count = 1, oi = 5, map = 1413, x = 54.8, y = 5.97, f = "e", note = "{item:8072}: Pick Pocket Foreman Silixiz", from = "Foreman Silixiz", fromKind = "npc", fromId = 7287, fromNpcs = { { npc = 7287, npcName = "Foreman Silixiz" } } },
					},
				},
				{
					title = "The Venture Co. tower",
					note = "Inside, floor by floor (everything comes back after 4 1/2 minutes): the Mutated Venture Co. Drones (level 25) on the ground floor die to one Ambush with a dagger; the Patrollers on the second floor take half their health from a one-point {spell:1943}; the Lookouts on the open third floor from a one-point {spell:2098}. {npc:7288} waits on the top floor: a level 23 elite, back 10 minutes after a kill. Open with Ambush (about half his health), then {spell:1776}, {spell:5277}, a healing potion and {item:7676}; a friend makes it easy. One head per kill. Then pick {object:129127} beside him for the cache: it poisons you with the {spell:9810}, which weakens your stealth and agility until {npc:2391} cures it.",
					goals = {
						{ t = "kill", quest = 2478, title = "Mission: Possible But Not Probable", target = "Mutated Venture Co. Drone", npc = 7310, count = 2, oi = 1, map = 1413, x = 54.7, y = 5.7, z = 93.3, f = "e" },
						{ t = "kill", quest = 2478, title = "Mission: Possible But Not Probable", target = "Venture Co. Patroller", npc = 7308, count = 2, oi = 3, map = 1413, x = 54.66, y = 5.68, z = 107.1, f = "e" },
						{ t = "kill", quest = 2478, title = "Mission: Possible But Not Probable", target = "Venture Co. Lookout", npc = 7307, count = 2, oi = 2, map = 1413, x = 54.64, y = 5.77, z = 120.7, f = "e" },
						{ t = "collect", quest = 2478, title = "Mission: Possible But Not Probable", item = 8074, itemName = "Gallywix's Head", count = 1, oi = 4, map = 1413, x = 54.75, y = 5.59, f = "e", note = "{item:8074}: {npc:7288} (elite)", from = "Grand Foreman Puzik Gallywix", fromKind = "npc", fromRank = 1, fromId = 7288, fromNpcs = { { npc = 7288, npcName = "Grand Foreman Puzik Gallywix" } }, group = { kind = "elite", rank = 1 } },
						{ t = "collect", quest = 2478, title = "Mission: Possible But Not Probable", item = 8073, itemName = "Cache of Zanzil's Altered Mixture", count = 1, oi = 6, map = 1413, x = 54.76, y = 5.56, f = "e", note = "{item:8073}: {object:129127}", from = "Gallywix's Lockbox", fromKind = "object", fromId = 129127 },
					},
				},
				{
					title = "Back to {npc:3401}",
					note = "Fly back to {zone:1454} ({area:392} or the {area:380}; dying at the tower and taking the spirit healer's way back to the {area:380} is quicker). Keep {item:8072} afterwards. Before you leave the {area:263}, buy {item:2928} and Empty Vials from Rekkul: once Hinott teaches Poisons, each batch of {item:6947} takes one of each.",
					goals = {
						{ t = "turnin", quest = 2478, title = "Mission: Possible But Not Probable", npc = 3401, npcName = "Shenthul", map = 1454, x = 43.05, y = 53.74, z = 7.8, f = "e", note = "{npc:3401}: {item:18160}", rewards = { items = { { item = 18160, itemName = "Recipe: Thistle Tea" } } } },
						{ t = "accept", quest = 2479, title = "Hinott's Assistance", npc = 3401, npcName = "Shenthul", minLevel = 20, qlvl = 26, pre = { 2478 }, preTitles = { [2478] = "Mission: Possible But Not Probable" }, map = 1454, x = 43.05, y = 53.74, z = 7.8, f = "e" },
					},
				},
				{
					title = "{npc:2391}",
					note = "Take the zeppelin from {zone:1454} to the {zone:1458} and follow the road south through {zone:1421} into {area:287}, to {area:272}. {npc:2391} works in the building next to the flight path, beside {npc:2216}, a wagon outside. If you lost the Sample of Zanzil's Mixture, abandon and retake from {npc:3401}. Stay beside him for about a minute while he brews the cure; if it never finishes, abandon and retake from him. Then open Poisons from your spellbook to make {item:6947} from Rekkul's dust and vials, and use it on your weapon.",
					goals = {
						{ t = "getfp", npc = 2389, npcName = "Zarise", location = "Tarren Mill", node = 13, area = 272, map = 1424, x = 60.14, y = 18.62, z = 58.9, f = "e", optional = true },
						{ t = "turnin", quest = 2479, title = "Hinott's Assistance", npc = 2391, npcName = "Serge Hinott", map = 1424, x = 61.63, y = 19.19, z = 57.6, f = "e" },
						{ t = "accept", quest = 2480, title = "Hinott's Assistance", npc = 2391, npcName = "Serge Hinott", minLevel = 20, qlvl = 20, pre = { 2479 }, preTitles = { [2479] = "Hinott's Assistance" }, map = 1424, x = 61.63, y = 19.19, z = 57.6, f = "e" },
						{ t = "complete", quest = 2480, title = "Hinott's Assistance", note = "Wait for the cure" },
						{ t = "turnin", quest = 2480, title = "Hinott's Assistance", npc = 2391, npcName = "Serge Hinott", map = 1424, x = 61.63, y = 19.19, z = 57.6, f = "e", note = "{npc:2391}: Poisons", rewards = { items = { { item = 8095, itemName = "Hinott's Oil" } } } },
						{ t = "use", item = 8095, itemName = "Hinott's Oil", map = 1424, x = 61.63, y = 19.19, f = "e", optional = true, note = "{item:8095}: clears the {spell:9810}" },
					},
				},
			},
		})
	end
	register()
end

