			written = { ["Back to {npc:205729} in {zone:1456}. He gives you the {item:206176} for his next test."] = "Back to Boarton in Thunder Bluff. He gives you the Mortar and Pestle for his next test.", ["Back to {npc:205729}. He hands you the {item:206344}: the fish must be filleted in front of him."] = "Back to Boarton. He hands you the Knife Set: the fish must be filleted in front of him.", ["Ride down the lift and south-east across {zone:1412} to the {area:360}. Put on the disguise, then open the carts of Blasting Supplies inside the mine and on the slope outside its far side; stay on the upper levels where you can, the lower tunnels are packed. Five charges."] = "Ride down the lift and south-east across Mulgore to the Venture Co. Mine. Put on the disguise, then open the carts of Blasting Supplies inside the mine and on the slope outside its far side; stay on the upper levels where you can, the lower tunnels are packed. Five charges.", ["Stand beside {npc:205729} and use the {item:206344} on the smallfish: it only counts next to him. Then take your weapon: the {item:277988} or the {item:278002}."] = "Stand beside Boarton and use the Knife Set on the smallfish: it only counts next to him. Then take your weapon: the Hoof-Holstered Blade or the Valley Cosh.", ["in front of {npc:205729}"] = "in front of Boarton" },
