						{ t = "accept", quest = 76240, title = "Stalk With The Earthmother", npc = 205729, npcName = "Boarton Shadetotem", minLevel = 4, qlvl = 11, map = 1456, x = 39.6, y = 65.84, f = "e", spotsPacked = "39.6,65.8,,15,23" },
