						{ t = "accept", quest = 2996, title = "Seeking Strahad", npc = 5875, npcName = "Gan'rul Bloodeye", minLevel = 30, qlvl = 30, closedBy = { 1801, 3001 }, preTitles = { [1801] = "Tome of the Cabal", [3001] = "Seeking Strahad" }, map = 1454, x = 48.25, y = 45.28, z = -14.8, f = "e" },
