					note = "At 30 {npc:5675}, in the {object:36082}, sends you to {npc:6251} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}. Take only one {quest:2996}: if {npc:6251} offers nothing, drop the duplicate from your log.",
					only = { races = { "Scourge" } },
					goals = {
						{ t = "level", level = 30 },
						{ t = "accept", quest = 3001, title = "Seeking Strahad", npc = 5675, npcName = "Carendin Halgar", minLevel = 30, qlvl = 30, closedBy = { 1801, 2996 }, preTitles = { [1801] = "Tome of the Cabal", [2996] = "Seeking Strahad" }, map = 1458, x = 85.06, y = 25.99, z = -62.2, f = "e" },
					},
				},
				{
					title = "{npc:6251}",
					note = "{area:392}'s flight point is a short flight from {zone:1454}'s. {npc:6251} stands on the hill above the town, behind the engineers' hut, by his little tower; {npc:6266} and two acolytes are with him. He sends you to {npc:6293} in the {zone:1458}.",
					goals = {
						{ t = "turnin", quest = 2996, title = "Seeking Strahad", npc = 6251, npcName = "Strahad Farsan", map = 1413, x = 62.63, y = 35.5, z = 40.5, f = "e", only = { races = { "Orc", "Troll" } } },
						{ t = "turnin", quest = 3001, title = "Seeking Strahad", npc = 6251, npcName = "Strahad Farsan", map = 1413, x = 62.63, y = 35.5, z = 40.5, f = "e", only = { races = { "Scourge" } } },
						{ t = "accept", quest = 1801, title = "Tome of the Cabal", npc = 6251, npcName = "Strahad Farsan", minLevel = 30, qlvl = 30, map = 1413, x = 62.63, y = 35.5, z = 40.5, f = "e" },
					},
				},
				{
					title = "{npc:6293}",
					note = "{npc:6293} is in the {object:36082} of the {zone:1458}. He wants two lost pieces of the {quest:1801}: one on the {area:287} coast, one in {zone:1441}.",
					goals = {
						{ t = "turnin", quest = 1801, title = "Tome of the Cabal", npc = 6293, npcName = "Jorah Annison", map = 1458, x = 75.92, y = 37.89, z = -62.1, f = "e" },
						{ t = "accept", quest = 1803, title = "Tome of the Cabal", npc = 6293, npcName = "Jorah Annison", minLevel = 30, qlvl = 30, pre = { 1801 }, preTitles = { [1801] = "Tome of the Cabal" }, map = 1458, x = 75.92, y = 37.89, z = -62.1, f = "e" },
					},
				},
				{
					title = "{item:6931}",
					note = "The tome is a small grey-blue book lying in the sand of a murloc camp on the shore south-west of {area:271}, near the water's edge. Six or seven murlocs guard it and more lurk underwater: they come in groups, so Fear one and keep your voidwalker on the rest. Walk down to the water to click it; from the hillside the crates block the cursor.",
					goals = {
