-- Source: forever/class/warlock/imp-horde.guide
do
	local function register()
		Polestar.RegisterGuide({
			id = "forever/class/warlock/imp-horde",
			pack = "guides",
			title = "Imp (Horde)",
			faction = "Horde",
			classes = { "WARLOCK" },
			minLevel = 1,
			maxLevel = 4,
			category = "Class",
			folder = "Warlock",
			keywords = { "Summon Imp", "Vile Familiars", "Piercing the Veil", "Ruzan", "Zureetha Fargaze", "Venya Marthand", "Vile Familiar Head", "Rattlecage Skull", "Burning Blade Coven", "Deathknell", "Tainted Parchment", "Tainted Tablet", "Tainted Scroll", "Primitive Hand Blade", "Primitive Walking Stick", "Warlock", "class pet" },
			reward = { { spell = 688, spellName = "Summon Imp" }, { item = 4925, itemName = "Primitive Hand Blade", choice = true }, { item = 5778, itemName = "Primitive Walking Stick", choice = true } },
			why = "Your first demon at level 1-4: the imp, with a starter blade or staff for Orcs and Trolls.",
			zone = 1411,
			zoneName = "Durotar",
			author = "Polestar",
			version = 1,
			names = { ["area:154"] = "Deathknell", ["area:363"] = "Valley of Trials", ["area:365"] = "Burning Blade Coven", ["item:282346"] = "Tainted Tablet", ["item:6281"] = "Rattlecage Skull", ["item:6487"] = "Vile Familiar Head", ["item:9578"] = "Tainted Scroll", ["item:9579"] = "Tainted Parchment", ["npc:1569"] = "Shadow Priest Sarvis", ["npc:1890"] = "Rattlecage Skeleton", ["npc:3145"] = "Zureetha Fargaze", ["npc:5667"] = "Venya Marthand", ["npc:5765"] = "Ruzan", ["quest:1485"] = "Vile Familiars", ["spell:688"] = "Summon Imp" },
			written = { ["{npc:5667} teaches you {spell:688} when you hand in the skulls: summon it right away, it costs nothing and fights beside you."] = "Venya teaches you Summon Imp when you hand in the skulls: summon it right away, it costs nothing and fights beside you." },
			steps = {
				{
					title = "{npc:5765} (Orcs and Trolls)",
					note = "Your first letter ({item:9579} for Orcs, {item:282346} for Trolls, from Gornek after Cutting Teeth) points you to Nartok, the warlock trainer in the Den. {npc:5765} stands just outside the Den in the {area:363} and asks for six Vile Familiar Heads.",
					only = { races = { "Orc", "Troll" } },
					goals = {
						{ t = "accept", quest = 1485, title = "Vile Familiars", npc = 5765, npcName = "Ruzan", minLevel = 1, qlvl = 4, closedBy = { 1470 }, preTitles = { [1470] = "Piercing the Veil" }, map = 1411, x = 42.59, y = 69, z = 38.2, f = "e" },
					},
				},
				{
					title = "{quest:1485}",
					note = "The {quest:1485} (level 3-4) swarm the {area:365}, the cave north of the Den, inside and around its mouth. Almost every kill drops a head (80%), so about eight kills does it; they throw small fireballs, so pull them one at a time. They respawn in just over three minutes. Other classes hunt the same imps for their own {quest:1485} quest.",
