					},
				},
				{
					title = "{area:2160}",
					note = "You need 15 Smoky Iron Ingots. The {area:2160} lies at the east end of {area:461}, east of {area:460}; every Windshear kobold (level 19-23) drops an ingot four kills in five. Stonecutters, Geomancers and Overlords run for help when low; Geomancers cast {spell:116}.",
					goals = {
						{ t = "collect", quest = 1838, title = "Brutal Armor", item = 7126, itemName = "Smoky Iron Ingot", count = 15, oi = 1, map = 1442, x = 71.76, y = 60.29, f = "e", spotsPacked = "72.4,61.3,,59,32;73.7,59.6,,53,18;75,58.9,,35,4", note = "{item:7126}, from the Windshear kobolds", from = "Windshear Vermin", fromKind = "npc", fromAlso = "Windshear Digger", fromId = 3998, fromAlsoId = 3999, fromNpcs = { { npc = 3998, npcName = "Windshear Vermin" }, { npc = 3999, npcName = "Windshear Digger" }, { npc = 4001, npcName = "Windshear Tunnel Rat" }, { npc = 4002, npcName = "Windshear Stonecutter" }, { npc = 4003, npcName = "Windshear Geomancer" } } },
