			written = { ["Keep it: {npc:5875} in {zone:1454}, at the end of this guide"] = "Keep it: Gan'rul in Orgrimmar, at the end of this guide", ["North to the {area:383}. {npc:3682} camps below the hills; {npc:261366}, the hermit on the ridge behind him, has work for you only once {npc:3682} sends you up."] = "North to the Dry Hills. Vrang Wildgore camps below the hills; Walton, the hermit on the ridge behind him, has work for you only once Vrang sends you up.", ["West of Gann, the Razormane hold {area:1701}. {npc:3436} is on the east side, {npc:3434} to the south, {npc:3435} at the west end. Lok (25) and the Warfrenzies (24-25) are a few levels above you; {npc:5859}, a rare elite, sometimes walks the ridge: leave him. Pathfinders and Stalkers drop the Backstabber, Seers the Wand, Warfrenzies the War Shield. {npc:3238} lizards and Hecklefang Stalkers roam the plain between {npc:3341} and the ridge. {quest:885}, a rare red wind serpent, flies over the ridge: its feather starts a quest.\nCareful: Razormane Stalkers move around in stealth and hit with {spell:1752}, so they can join a fight without warning."] = "West of Gann, the Razormane hold Blackthorn Ridge. Kuz is on the east side, Nak to the south, Lok Orcbane at the west end. Lok (25) and the Warfrenzies (24-25) are a few levels above you; Hagg Taurenbane, a rare elite, sometimes walks the ridge: leave him. Pathfinders and Stalkers drop the Backstabber, Seers the Wand, Warfrenzies the War Shield. Stormhide lizards and Hecklefang Stalkers roam the plain between Gann and the ridge. Washte Pawne, a rare red wind serpent, flies over the ridge: its feather starts a quest.\nCareful: Razormane Stalkers move around in stealth and hit with Sinister Strike, so they can join a fight without warning.", ["{area:380}"] = "The Crossroads", ["{npc:11802}: the welcome from {npc:3033}"] = "Dendrite Starblaze: the welcome from Turak", ["{npc:14242}, up in the tree just east of {npc:3341}"] = "Sulhasa, up in the tree just east of Gann", ["{npc:3341} waits in a small camp further south, on the road toward {area:359}."] = "Gann waits in a small camp further south, on the road toward Bael Modan.", ["{npc:3389} stands at the Kolkar watch post just west of the {area:380}."] = "Regthar stands at the Kolkar watch post just west of the Crossroads.", ["{npc:3394} stands in the Kolkar camp north-west of {npc:3389}."] = "Barak stands in the Kolkar camp north-west of Regthar.", ["{npc:3395} walks among the Kolkar at the {area:388} south-east of the {area:380}."] = "Verog walks among the Kolkar at the Stagnant Oasis south-east of the Crossroads.", ["{npc:3396} leads the Kolkar on the west shore of {area:387}, south of {npc:3389}. Hand his head to {npc:3389} on your last {area:380} stop."] = "Hezrul leads the Kolkar on the west shore of Lushwater Oasis, south of Regthar. Hand his head to Regthar on your last Crossroads stop.", ["{npc:4197} lives in {area:2539}, the troll village just inside Stonetalon at the end of the road west from {npc:3389}."] = "Ken'zigla lives in Malaka'jin, the troll village just inside Stonetalon at the end of the road west from Regthar.", ["{npc:5878} camps beside the road east of the {area:380}."] = "Thun'grim camps beside the road east of the Crossroads.", ["{npc:5899}, just west of {npc:3341}"] = "Brine, just west of Gann", ["{npc:5901} waits on the hill south of {area:392}, on your way north."] = "Islen waits on the hill south of Ratchet, on your way north." },
